#include <stdio.h>
#include <stdlib.h>

typedef long long ll;

// Comparison function for sorting in descending order
int cmp_desc(const void *a, const void *b) {
    ll x = *(const ll*)a;
    ll y = *(const ll*)b;
    if (x > y) return -1;
    if (x < y) return 1;
    return 0;
}

int main() {
    int N, K, M;
    scanf("%d %d %d", &N, &K, &M);

    ll *votes = (ll*)malloc(N * sizeof(ll));
    int *is_favorite = (int*)calloc(N, sizeof(int));

    for (int i = 0; i < N; i++) {
        scanf("%lld", &votes[i]);
    }

    for (int i = 0; i < M; i++) {
        int idx;
        scanf("%d", &idx);
        is_favorite[idx - 1] = 1;
    }

    ll L;
    scanf("%lld", &L);

    // Separate favorites and non-favorites
    ll *fav = (ll*)malloc(M * sizeof(ll));
    ll *non_fav = (ll*)malloc((N - M) * sizeof(ll));
    int fav_cnt = 0, non_cnt = 0;

    for (int i = 0; i < N; i++) {
        if (is_favorite[i]) {
            fav[fav_cnt++] = votes[i];
        } else {
            non_fav[non_cnt++] = votes[i];
        }
    }

    // Sort non-favorites in descending order
    qsort(non_fav, non_cnt, sizeof(ll), cmp_desc);

    // Sort favorites in descending order
    qsort(fav, fav_cnt, sizeof(ll), cmp_desc);

    // Binary search on answer: maximum number of favorites in top K
    int left = 0, right = M;
    int ans = 0;

    while (left <= right) {
        int mid = (left + right) / 2;

        // Check if we can get 'mid' favorites into top K
        // We will try to make the 'mid' best favorites as high as possible
        // and suppress the top (K - mid) non-favorites if needed

        // Take the top 'mid' favorites
        ll *selected_fav = fav; // already sorted descending
        // We need to ensure that the worst among these mid favorites 
        // (i.e., the mid-th favorite) can be in top K.

        // The top K positions will consist of:
        // - These 'mid' favorites (with boosted votes)
        // - The best (K - mid) non-favorites (which we may try to suppress)

        if (mid > K) {
            // Cannot have more than K favorites in top K
            right = mid - 1;
            continue;
        }

        // We need to check if we can allocate votes so that:
        // All 'mid' favorites are >= the (K-mid)-th non-favorite (if any)
        // and also the 'mid' favorite with smallest initial votes can be boosted enough.

        // The worst-case threshold is the (K-mid)-th non-favorite's vote (if exists),
        // or we just need to be above 0.

        ll threshold = 0;
        if (K - mid > 0 && K - mid <= non_cnt) {
            threshold = non_fav[K - mid - 1]; // (K-mid)-th highest non-favorite
        } else if (K - mid > non_cnt) {
            // If there are not enough non-favorites, threshold is 0
            threshold = 0;
        } else {
            // K - mid == 0, no non-favorites in top K, threshold is 0
            threshold = 0;
        }

        // Now we need to see if we can boost the 'mid' favorites
        // such that each of them is at least threshold+1 (to beat the non-favorite)
        // or at least their current vote (if already higher).

        ll needed = 0;
        int possible = 1;

        for (int i = 0; i < mid; i++) {
            ll current = selected_fav[i];
            if (current > threshold) {
                // Already above threshold, no votes needed
                continue;
            } else {
                // Need to raise to threshold + 1
                needed += (threshold + 1 - current);
                if (needed > L) {
                    possible = 0;
                    break;
                }
            }
        }

        // Also need to consider that non-favorites might also get votes?
        // No, we only control our votes. We don't give votes to non-favorites.
        // However, the non-favorites' votes are fixed as predicted.
        // So we just need to make our favorites surpass the threshold.

        if (possible && needed <= L) {
            // But we also need to consider that we might need to boost more than 'mid' favorites?
            // No, we only care about these 'mid' being in top K.
            // However, there is a subtlety: what if some of our other favorites
            // (not in the top 'mid') also surpass the threshold and push out a non-favorite?
            // That would only help us, not hurt. So it's fine.

            // Also we must ensure that the boosted favorites don't exceed L votes total.
            // Already checked.

            ans = mid;
            left = mid + 1;
        } else {
            right = mid - 1;
        }
    }

    printf("%d\n", ans);

    free(votes);
    free(is_favorite);
    free(fav);
    free(non_fav);

    return 0;
}

