typedef long long ll;

static int cmp_ll(const void *a, const void *b) {
    ll x = *(const ll *)a;
    ll y = *(const ll *)b;
    if (x < y) return -1;
    if (x > y) return 1;
    return 0;
}

int main(void) {
    int N, M, K;
    ll L;
    if (scanf("%d %d %d %lld", &N, &M, &K, &L) != 4) return 0;

    ll *fav = (ll *)malloc(sizeof(ll) * M);
    ll *other = (ll *)malloc(sizeof(ll) * (N - M));
    int i;
    for (i = 0; i < M; i++) scanf("%lld", &fav[i]);
    for (i = 0; i < N - M; i++) scanf("%lld", &other[i]);

    qsort(fav, M, sizeof(ll), cmp_ll);
    qsort(other, N - M, sizeof(ll), cmp_ll);

    /* Prefix sums of favorites */
    ll *pf = (ll *)malloc(sizeof(ll) * (M + 1));
    pf[0] = 0;
    for (i = 0; i < M; i++) pf[i + 1] = pf[i] + fav[i];

    /*
      We want to maximize x = number of favorites in top K.

      Necessary and sufficient condition for achieving x:
      choose x favorites and make each of them strictly greater than at least
      N-K characters, i.e. greater than the (N-K)-th smallest final vote.

      To minimize needed votes for x favorites:
      - keep all non-chosen favorites unchanged
      - threshold t should be as small as possible
      - among non-chosen characters, the smallest N-K must stay below chosen ones.
        Since we can choose which favorites to promote, best is to leave the
        M-x smallest favorites unchosen. Then among all unchanged characters
        (other + unchosen favorites), the threshold base is the (N-K)-th smallest.
      - chosen favorites should be the x largest favorites, because raising larger
        values costs less.

      Let S = multiset(other) U {smallest M-x favorites}.
      Need each chosen favorite > T where T is the (N-K)-th smallest in S
      (0-indexed count meaning exactly N-K elements <= T possible; strict > T).
      Minimal final for each chosen is T+1.

      Edge case: if N-K == 0, threshold is effectively -infinity, so 0 cost.
    */

    int low = 0, high = (M < K ? M : K), ans = 0;

    while (low <= high) {
        int x = (low + high) / 2;
        int unchosenFav = M - x;

        ll need = 0;

        if (N - K > 0) {
            int needRank = N - K; // need the needRank-th smallest, 1-based
            ll T;

            if (needRank <= 0) {
                T = -(1LL << 60);
            } else {
                int a = unchosenFav;
                int b = N - M;

                /* Find needRank-th smallest in merge of fav[0..a-1] and other[0..b-1] */
                if (a == 0) {
                    T = other[needRank - 1];
                } else if (b == 0) {
                    T = fav[needRank - 1];
                } else {
                    int ia = 0, ib = 0, cnt = 0;
                    T = 0;
                    while (cnt < needRank) {
                        if (ia < a && (ib >= b || fav[ia] <= other[ib])) {
                            T = fav[ia++];
                        } else {
                            T = other[ib++];
                        }
                        cnt++;
                    }
                }
            }

            ll target = T + 1;

            /* chosen favorites are fav[M-x .. M-1] */
            int start = M - x;

            /* first index in chosen range with fav[idx] < target */
            int l = start, r = M;
            while (l < r) {
                int mid = (l + r) / 2;
                if (fav[mid] >= target) r = mid;
                else l = mid + 1;
            }
            int pos = l;
            int cntRaise = pos - start;
            if (cntRaise > 0) {
                need = (ll)cntRaise * target - (pf[pos] - pf[start]);
            } else {
                need = 0;
            }
        } else {
            need = 0;
        }

        if (need <= L) {
            ans = x;
            low = x + 1;
        } else {
            high = x - 1;
        }
    }

    printf("%d\n", ans);

    free(fav);
    free(other);
    free(pf);
    return 0;
}

