public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int N = Integer.parseInt(st.nextToken());
        int K = Integer.parseInt(st.nextToken());
        int L = Integer.parseInt(st.nextToken());
        int M = Integer.parseInt(st.nextToken());

        long[] votes = new long[N];
        boolean[] favorite = new boolean[N];

        st = new StringTokenizer(br.readLine());
        for (int i = 0; i < N; i++) {
            votes[i] = Long.parseLong(st.nextToken());
        }

        st = new StringTokenizer(br.readLine());
        for (int i = 0; i < M; i++) {
            int idx = Integer.parseInt(st.nextToken()) - 1;
            favorite[idx] = true;
        }

        // Binary search on the answer: maximum number of favorites we can get into top K
        int left = 0, right = M;
        while (left < right) {
            int mid = (left + right + 1) / 2;
            if (canAchieve(mid, N, K, L, votes, favorite)) {
                left = mid;
            } else {
                right = mid - 1;
            }
        }
        System.out.println(left);
    }

    static boolean canAchieve(int target, int N, int K, int L, long[] votes, boolean[] favorite) {
        // We need at least target favorites in top K
        // First, collect all characters with their votes and favorite status
        Character[] chars = new Character[N];
        for (int i = 0; i < N; i++) {
            chars[i] = new Character(votes[i], favorite[i], i);
        }

        // Sort by votes descending, break ties by favorite status (favorites first)
        Arrays.sort(chars, (a, b) -> {
            if (a.votes != b.votes) return Long.compare(b.votes, a.votes);
            if (a.isFavorite != b.isFavorite) return a.isFavorite ? -1 : 1;
            return 0;
        });

        // Track which positions are currently in top K
        boolean[] inTopK = new boolean[N];
        int favInTopK = 0;

        // Initial top K
        for (int i = 0; i < K; i++) {
            inTopK[chars[i].id] = true;
            if (chars[i].isFavorite) favInTopK++;
        }

        // If already have enough favorites, return true
        if (favInTopK >= target) return true;

        // We need to get more favorites into top K
        // For each favorite not in top K, calculate minimum votes needed to push in
        // We'll use a greedy approach: try to replace non-favorites in top K with favorites

        // Collect non-favorites in top K and favorites not in top K
        List<Integer> nonFavInTopK = new ArrayList<>();
        List<Integer> favNotInTopK = new ArrayList<>();

        for (int i = 0; i < N; i++) {
            if (inTopK[i] && !favorite[i]) {
                nonFavInTopK.add(i);
            }
            if (!inTopK[i] && favorite[i]) {
                favNotInTopK.add(i);
            }
        }

        // Sort non-favorites in top K by votes ascending (easiest to replace)
        nonFavInTopK.sort((a, b) -> Long.compare(votes[a], votes[b]));
        // Sort favorites not in top K by votes descending (closest to getting in)
        favNotInTopK.sort((a, b) -> Long.compare(votes[b], votes[a]));

        long votesNeeded = 0;
        int replaced = 0;

        for (int i = 0; i < Math.min(nonFavInTopK.size(), favNotInTopK.size()) && replaced < target - favInTopK; i++) {
            int nonFavId = nonFavInTopK.get(i);
            int favId = favNotInTopK.get(i);

            // To get favorite in, we need votes[favId] + added > votes[nonFavId]
            // or equal with tie-breaking favoring favorite (which we already have)
            long needed = votes[nonFavId] - votes[favId] + 1;
            if (needed > 0) {
                votesNeeded += needed;
            }
            replaced++;
        }

        // Also consider case where we might need to replace multiple non-favorites
        // for one favorite if there are ties, but the greedy approach works for the general case

        // Check if we can also push in favorites by giving them more votes without replacing
        // This is handled by the fact that we compare against the K-th position

        // More accurate approach: binary search on the threshold vote
        // We'll use a different method: determine the minimum votes needed for target favorites to be in top K

        // Alternative approach: For each possible threshold, check if we can get target favorites above it
        long low = 0, high = 2000000000L;
        while (low < high) {
            long mid = (low + high) / 2;
            if (canAchieveWithThreshold(target, N, K, L, votes, favorite, mid)) {
                high = mid;
            } else {
                low = mid + 1;
            }
        }

        // Check if we can achieve with votes = low
        return canAchieveWithThreshold(target, N, K, L, votes, favorite, low);
    }

    static boolean canAchieveWithThreshold(int target, int N, int K, long L, long[] votes, boolean[] favorite, long threshold) {
        // Count how many favorites can be in top K if we give votes to reach threshold
        // For each character, consider their final votes after allocation
        long[] finalVotes = new long[N];
        for (int i = 0; i < N; i++) {
            finalVotes[i] = votes[i];
        }

        long votesUsed = 0;
        int favCount = 0;

        // First, give votes to favorites to reach threshold if needed
        for (int i = 0; i < N; i++) {
            if (favorite[i] && finalVotes[i] < threshold) {
                long needed = threshold - finalVotes[i];
                if (votesUsed + needed <= L) {
                    votesUsed += needed;
                    finalVotes[i] = threshold;
                } else {
                    // Can't give enough, give what we can
                    finalVotes[i] += L - votesUsed;
                    votesUsed = L;
                }
            }
        }

        // Now count how many favorites are in top K
        // Sort by final votes
        Character[] chars = new Character[N];
        for (int i = 0; i < N; i++) {
            chars[i] = new Character(finalVotes[i], favorite[i], i);
        }

        Arrays.sort(chars, (a, b) -> {
            if (a.votes != b.votes) return Long.compare(b.votes, a.votes);
            if (a.isFavorite != b.isFavorite) return a.isFavorite ? -1 : 1;
            return 0;
        });

        for (int i = 0; i < K; i++) {
            if (chars[i].isFavorite) favCount++;
        }

        return favCount >= target;
    }

    static class Character {
        long votes;
        boolean isFavorite;
        int id;

        Character(long v, boolean f, int i) {
            votes = v;
            isFavorite = f;
            id = i;
        }
    }
}

