                threshold = nonFavVotes.get(slotsForNonFav); // need to beat this
            }

            // Cost for each favorite to reach threshold
            int[] cost = new int[M];
            for (int i = 0; i < M; i++) {
                cost[i] = Math.max(0, threshold - favVotes[i] + 1);
            }
            Arrays.sort(cost);

