import java.io.*;
import java.util.*;

public class Main {
    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            long sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            long val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }

        int nextInt() throws IOException {
            return (int) nextLong();
        }
    }

    static class Character {
        long votes;
        boolean favorite;

        Character(long votes, boolean favorite) {
            this.votes = votes;
            this.favorite = favorite;
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);

        int N = fs.nextInt();
        int M = fs.nextInt();
        int K = fs.nextInt();
        long L = fs.nextLong();

        boolean[] fav = new boolean[N];
        for (int i = 0; i < M; i++) {
            int x = fs.nextInt() - 1;
            fav[x] = true;
        }

        Character[] arr = new Character[N];
        for (int i = 0; i < N; i++) {
            long a = fs.nextLong();
            arr[i] = new Character(a, fav[i]);
        }

        Arrays.sort(arr, (c1, c2) -> Long.compare(c2.votes, c1.votes));

        ArrayList<Long> nonFavVotes = new ArrayList<>();
        ArrayList<Long> favVotes = new ArrayList<>();
        for (Character c : arr) {
            if (c.favorite) favVotes.add(c.votes);
            else nonFavVotes.add(c.votes);
        }

        int F = favVotes.size();
        int O = nonFavVotes.size();

        long[] prefNon = new long[O + 1];
        for (int i = 0; i < O; i++) prefNon[i + 1] = prefNon[i] + nonFavVotes.get(i);

        long[] favAsc = new long[F];
        for (int i = 0; i < F; i++) favAsc[i] = favVotes.get(F - 1 - i);

        long[] prefFavAsc = new long[F + 1];
        for (int i = 0; i < F; i++) prefFavAsc[i + 1] = prefFavAsc[i] + favAsc[i];

        int maxPossible = Math.min(M, K);
        int answer = 0;

        for (int x = 0; x <= maxPossible; x++) {
            int needOthers = K - x;
            if (needOthers > O) continue;
            if (x > F) continue;

            long threshold;
            if (needOthers == 0) {
                threshold = 0;
            } else {
                threshold = nonFavVotes.get(needOthers - 1);
            }

            int cntLess = lowerBound(favAsc, threshold); // in ascending favAsc
            int cntEq = upperBound(favAsc, threshold) - cntLess;

            if (cntLess > x) continue;
            if (cntLess + cntEq < x) continue;

            long cost = 0;

            // All favorites with votes < threshold need to be raised to threshold
            cost += (long) cntLess * threshold - prefFavAsc[cntLess];

            // Need choose (x - cntLess) among those == threshold, each needs +1
            cost += (x - cntLess);

            if (cost <= L) answer = x;
        }

        System.out.println(answer);
    }

    static int lowerBound(long[] a, long key) {
        int l = 0, r = a.length;
        while (l < r) {
            int m = (l + r) >>> 1;
            if (a[m] >= key) r = m;
            else l = m + 1;
        }
        return l;
    }

    static int upperBound(long[] a, long key) {
        int l = 0, r = a.length;
        while (l < r) {
            int m = (l + r) >>> 1;
            if (a[m] > key) r = m;
            else l = m + 1;
        }
        return l;
    }
}

