int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, K, M;
    ll L;
    cin >> N >> K >> M >> L;

    vector<ll> votes(N);
    for (int i = 0; i < N; i++) {
        cin >> votes[i];
    }

    vector<int> fav(N, 0);
    for (int i = 0; i < M; i++) {
        int idx;
        cin >> idx;
        fav[idx] = 1;
    }

