    // Binary search on answer t: can we get at least t favorites into top K?

    int lo = 0, hi = M, best = 0;
    while (lo <= hi) {
        int mid = (lo + hi) / 2;

        // Check if we can get at least 'mid' favorites into top K
        // Strategy: 
        // 1. For each favorite, we consider the minimum votes needed to secure a top K spot.
        // 2. Sort favorites by the additional votes needed (or by current votes).
        // 3. Use L votes to push the 'mid' most promising favorites into top K.

        // We'll create a list of all characters with their current votes and favorite flag.
        // To check feasibility for 'mid':
        // We need to select 'mid' favorites that we will push into top K.
        // For each candidate set, we need to ensure we can allocate votes so that:
        //   - Those 'mid' favorites end up in top K.
        //   - The total votes used <= L.

        // A greedy approach: sort favorites by current votes descending.
        // For each favorite, compute how many votes are needed to be "safe" in top K.
        // The safe threshold is the K-th highest vote after optimal allocation,
        // but we can approximate by considering the worst-case non-favorites.

        // Collect non-favorite votes
        vector<ll> nonFav;
        for (int i = 0; i < N; i++) {
            if (!fav[i]) nonFav.push_back(votes[i]);
        }
        sort(nonFav.rbegin(), nonFav.rend());

        // Get favorite votes
        vector<pair<ll,int>> favVotes;
        for (int i = 0; i < N; i++) {
            if (fav[i]) favVotes.push_back({votes[i], i});
        }
        sort(favVotes.rbegin(), favVotes.rend());

        // If there are fewer favorites than 'mid', impossible
        if ((int)favVotes.size() < mid) {
            hi = mid - 1;
            continue;
        }

        bool possible = false;

        // We'll try to select 'mid' favorites that we will push.
        // Since M <= 10, we can brute-force combinations if needed,
        // but M can be up to N. However, K is up to N, N up to 1e5.
        // We need a smarter method.

        // Alternative: binary search on answer and use a greedy check.
        // For a given 'mid', we want to know if we can make 'mid' favorites
        // be among the top K after adding votes.
        // 
        // Observation: To get a favorite into top K, we need its final votes
        // to be at least as high as the K-th highest final vote among all.
        // The worst-case for us is that non-favorites get no extra votes.
        // So the threshold is at least the K-th highest non-favorite vote
        // (since favorites we don't push might be below them).
        //
        // But we can also add votes to non-favorites? No, we only allocate votes
