        vector<ll> needed;
        for (auto &p : favVotes) {
            ll cur = p.first;
            ll add = max(0LL, threshold + 1 - cur);
            needed.push_back(add);
        }
        sort(needed.begin(), needed.end());

        ll total = 0;
        for (int i = 0; i < mid; i++) {
            total += needed[i];
            if (total > L) break;
        }
        if (total <= L) {
            possible = true;
        }

        if (possible) {
            best = mid;
            lo = mid + 1;
        } else {
            hi = mid - 1;
        }
