#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, M, K;
    long long L;
    cin >> N >> M >> K >> L;

    vector<long long> a(N);
    for (int i = 0; i < N; i++) cin >> a[i];

    vector<int> favIdx(M);
    vector<int> isFav(N, 0);
    for (int i = 0; i < M; i++) {
        cin >> favIdx[i];
        --favIdx[i];
        isFav[favIdx[i]] = 1;
    }

    vector<long long> fav, other;
    for (int i = 0; i < N; i++) {
        if (isFav[i]) fav.push_back(a[i]);
        else other.push_back(a[i]);
    }

    sort(fav.begin(), fav.end(), greater<long long>());
    sort(other.begin(), other.end(), greater<long long>());

    int maxTake = min(M, K);

    auto can = [&](int x) -> bool {
        // Try to make x favorites be in top K.
        // Best choice: use the x favorites with largest base votes.
        // We need each selected favorite to end with votes > threshold,
        // where threshold is the (K-x)-th largest among non-selected characters.
        if (x == 0) return true;
        if (x > (int)fav.size() || x > K) return false;

        int needOthers = K - x;

        vector<long long> rest;
        rest.reserve((int)fav.size() - x + (int)other.size());

        for (int i = x; i < (int)fav.size(); i++) rest.push_back(fav[i]);
        for (long long v : other) rest.push_back(v);

        sort(rest.begin(), rest.end(), greater<long long>());

        long long threshold;
        if (needOthers == 0) {
            threshold = -1; // no one else needs to be above
        } else {
            threshold = rest[needOthers - 1];
        }

        long long cost = 0;
        for (int i = 0; i < x; i++) {
            if (fav[i] <= threshold) {
                cost += (threshold + 1 - fav[i]);
                if (cost > L) return false;
            }
        }
        return cost <= L;
    };

    int lo = 0, hi = maxTake;
    while (lo < hi) {
        int mid = (lo + hi + 1) / 2;
        if (can(mid)) lo = mid;
        else hi = mid - 1;
    }

    cout << lo << '\n';
    return 0;
}
